package com.ecole.gestion_scolaire.registration.service; import com.ecole.gestion_scolaire.registration.dto.*; import com.ecole.gestion_scolaire.registration.entity.*; import com.ecole.gestion_scolaire.registration.exception.RegistrationValidationException; import com.ecole.gestion_scolaire.registration.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.OffsetDateTime; import java.util.*;
@Service @Transactional(readOnly=true) public class RegistrationDocumentService {private final RegistrationDocumentRequirementRepository reqs;private final RegistrationDocumentStatusRepository statuses;private final RegistrationCaseService cases;private final CurrentAccountService current;public RegistrationDocumentService(RegistrationDocumentRequirementRepository r,RegistrationDocumentStatusRepository s,RegistrationCaseService c,CurrentAccountService u){reqs=r;statuses=s;cases=c;current=u;}
 public List<RegistrationDocumentRequirementResponse> requirements(){return reqs.findByActiveTrueOrderByNameAsc().stream().map(this::mapReq).toList();}@Transactional public RegistrationDocumentRequirementResponse createRequirement(RegistrationDocumentRequirementRequest r){String code=r.code().trim().toUpperCase(Locale.ROOT);if(reqs.findByCode(code).isPresent())throw new RegistrationValidationException("Code de pièce déjà utilisé : "+code);var x=new RegistrationDocumentRequirement();x.setCode(code);x.setName(r.name().trim());x.setApplicableTo(r.applicableTo().trim().toUpperCase(Locale.ROOT));x.setRequired(r.required());x.setActive(r.active());return mapReq(reqs.save(x));}
 public List<RegistrationDocumentStatusResponse> list(Long caseId){cases.get(caseId);return statuses.findByRegistrationCaseIdOrderByRequirementNameAsc(caseId).stream().map(this::mapStatus).toList();}
 @Transactional public RegistrationDocumentStatusResponse save(Long caseId,RegistrationDocumentStatusRequest r){var req=reqs.findById(r.requirementId()).orElseThrow(()->new RegistrationValidationException("Pièce requise introuvable : "+r.requirementId()));var x=statuses.findByRegistrationCaseIdAndRequirementId(caseId,r.requirementId()).orElseGet(()->{var n=new RegistrationDocumentStatus();n.setRegistrationCase(cases.get(caseId));n.setRequirement(req);return n;});x.setProvided(r.provided());x.setProvidedAt(r.provided()?(x.getProvidedAt()==null?OffsetDateTime.now():x.getProvidedAt()):null);x.setVerified(r.provided()&&r.verified());x.setVerifiedById(x.isVerified()?current.id():null);x.setVerifiedAt(x.isVerified()?OffsetDateTime.now():null);x.setNotes(r.notes());return mapStatus(statuses.save(x));}
 public void initialize(Long caseId){var c=cases.get(caseId);for(var req:reqs.findByActiveTrueOrderByNameAsc())if(statuses.findByRegistrationCaseIdAndRequirementId(caseId,req.getId()).isEmpty()){var s=new RegistrationDocumentStatus();s.setRegistrationCase(c);s.setRequirement(req);s.setProvided(false);s.setVerified(false);statuses.save(s);}}
 private RegistrationDocumentRequirementResponse mapReq(RegistrationDocumentRequirement x){return new RegistrationDocumentRequirementResponse(x.getId(),x.getCode(),x.getName(),x.getApplicableTo(),x.isRequired(),x.isActive());} private RegistrationDocumentStatusResponse mapStatus(RegistrationDocumentStatus x){var r=x.getRequirement();return new RegistrationDocumentStatusResponse(x.getId(),x.getRegistrationCase().getId(),r.getId(),r.getCode(),r.getName(),r.isRequired(),x.isProvided(),x.getProvidedAt(),x.isVerified(),x.getVerifiedById(),x.getVerifiedAt(),x.getNotes());}
}
